import{c as d,Q as r,j as e,m as a}from"./chunks/framework.rWdQudnF.js";const b=JSON.parse('{"title":"架构师-备考 综合知识-系统基础-计算机组成-总线结构","description":"","frontmatter":{"title":"架构师-备考 综合知识-系统基础-计算机组成-总线结构"},"headers":[],"relativePath":"综合知识/系统基础/计算机组成/存储与IO系统/总线结构.md","filePath":"综合知识/系统基础/计算机组成/存储与IO系统/总线结构.md","lastUpdated":null}'),o={name:"综合知识/系统基础/计算机组成/存储与IO系统/总线结构.md"};function n(s,t,l,h,i,g){return r(),e("div",null,[...t[0]||(t[0]=[a('<h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="总线结构-★" tabindex="-1">总线结构 ★ <a class="header-anchor" href="#总线结构-★" aria-label="Permalink to &quot;总线结构 ★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层级</th><th>作用域</th><th>关键特征</th></tr></thead><tbody><tr><td><strong>内部总线</strong>（片内）</td><td>芯片内部</td><td>高带宽、低延迟、不对外开放</td></tr><tr><td><strong>系统总线</strong>（板级）</td><td>主板+扩展槽</td><td>决定内存最大容量，三总线并行</td></tr><tr><td><strong>外部总线</strong>（设备级）</td><td>机箱外设</td><td>热插拔、即插即用</td></tr></tbody></table><p><strong>系统总线&quot;三驾马车&quot;：</strong></p><table tabindex="0"><thead><tr><th>总线</th><th style="text-align:center;">方向</th><th>作用</th></tr></thead><tbody><tr><td><strong>数据总线</strong></td><td style="text-align:center;">双向</td><td>传输数据，宽度 = 字长倍数</td></tr><tr><td><strong>地址总线</strong></td><td style="text-align:center;">单向</td><td>传输地址，宽度决定<strong>寻址空间</strong></td></tr><tr><td><strong>控制总线</strong></td><td style="text-align:center;">—</td><td>传输控制信号（读/写/中断/时钟等）</td></tr></tbody></table><h4 id="串行总线-vs-并行总线-★" tabindex="-1">串行总线 vs 并行总线 ★ <a class="header-anchor" href="#串行总线-vs-并行总线-★" aria-label="Permalink to &quot;串行总线 vs 并行总线 ★&quot;">​</a></h4><blockquote><p>🎯 一句话结论：<strong>并行总线适合短距离高速传输，串行总线适合长距离</strong>；PCI 是并行总线，USB/SATA/RapidIO/PCIe 是串行总线。</p></blockquote><table tabindex="0"><thead><tr><th>对比</th><th>串行总线</th><th>并行总线</th></tr></thead><tbody><tr><td>传输方式</td><td>逐位（bit）串行发送</td><td>多根数据线同时发送多位</td></tr><tr><td>代表接口</td><td>USB, SATA, RS-232, RapidIO, PCIe</td><td><strong>PCI</strong>, IDE(PATA), LPT</td></tr><tr><td>传输距离</td><td>适宜<strong>长距离</strong></td><td>适宜<strong>短距离</strong></td></tr><tr><td>信号同步</td><td>嵌入时钟或异步</td><td>需同时到达，高频难度大</td></tr><tr><td>波特率</td><td>初始化时预定义，使用中不变</td><td>—</td></tr></tbody></table><blockquote><p>⚠️ 易混淆：<strong>PCI ≠ PCIe</strong>。PCI 是并行总线，PCI Express (PCIe) 是串行总线。考题常把 PCI 混入&quot;以下属于串行总线的是&quot;选项中。</p></blockquote><h4 id="串行总线波特率" tabindex="-1">串行总线波特率 <a class="header-anchor" href="#串行总线波特率" aria-label="Permalink to &quot;串行总线波特率&quot;">​</a></h4><blockquote><p>🎯 一句话结论：<strong>串行总线波特率在总线初始化时预先定义，使用中不可改变</strong>。</p></blockquote><ul><li>波特率（Baud Rate）= 每秒传输的信号单元数（不同于比特率）</li><li>常见标准波特率：9600, 19200, 38400, 115200 等</li><li>并非所有串行总线都是全双工（I²C 是半双工/同步串行）</li><li>数据正确性依赖校验码（奇偶校验、CRC）而非仅靠纠错码</li></ul>',12)])])}const u=d(o,[["render",n]]);export{b as __pageData,u as default};
